package mrpapermoon.whisper.screenimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.Boximport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.sizeimport androidx.compose.foundation.shape.CircleShapeimport androidx.compose.material.Iconimport androidx.compose.material.MaterialThemeimport androidx.compose.runtime.Composableimport androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.draw.clipimport androidx.compose.ui.graphics.vector.ImageVectorimport androidx.compose.ui.res.vectorResourceimport androidx.compose.ui.tooling.preview.Previewimport androidx.compose.ui.unit.dpimport mrpapermoon.whisper.Rimport mrpapermoon.whisper.ui.theme.WhisperTheme@Composablefun SplashContent(	modifier: Modifier = Modifier,	useIconBackground: Boolean = false,) {	Box(		modifier = modifier			.fillMaxSize()			.background(MaterialTheme.colors.background),		contentAlignment = Alignment.Center	) {		val appIcon = ImageVector.vectorResource(R.drawable.outline_bring_your_own_ip_24)		if (useIconBackground) {			CircleAppIcon(appIcon)		} else {			FlatAppIcon(appIcon)		}	}}@Composableprivate fun CircleAppIcon(appIcon: ImageVector) {	Box(		modifier = Modifier			.size(240.dp),		contentAlignment = Alignment.Center	) {		Box(			modifier = Modifier				.size(160.dp)				.clip(CircleShape)				.background(MaterialTheme.colors.secondary),			contentAlignment = Alignment.Center		) {			Icon(				imageVector = appIcon,				contentDescription = null,				tint = MaterialTheme.colors.onSecondary,				modifier = Modifier.size(106.dp)			)		}	}}@Composableprivate fun FlatAppIcon(appIcon: ImageVector) {	Box(		modifier = Modifier			.size(288.dp),		contentAlignment = Alignment.Center	) {		Box(			modifier = Modifier				.size(192.dp),			contentAlignment = Alignment.Center		) {			Icon(				imageVector = appIcon,				contentDescription = null,				tint = MaterialTheme.colors.secondary,				modifier = Modifier.fillMaxSize()			)		}	}}@Preview(name = "Background Mode", showBackground = true)@Composablefun SplashPreviewWBg() {	WhisperTheme {		SplashContent(useIconBackground = true)	}}@Preview(name = "Flat Mode", showBackground = true)@Composablefun SplashPreview() {	WhisperTheme {		SplashContent()	}}